#include "ReagentWorks.h"
#include "WaterWorks.h"
#include "Power.h"
#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace aftertaste;using K=MachineKind;using E=EnergyMedium;
static int checks=0;static void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
static Factory empty(){Factory f;f.machines.clear();f.energyLinks.clear();f.blueprints.clear();f.waterworks=WaterWorksState{};f.water=0;f.electricity=100000;return f;}
static Machine& add(Factory& f,Position p,K k,int d=0){Machine m;m.kind=k;m.dir=d;initialisePowerDevice(m);return f.machines.emplace(p,m).first->second;}
static void advance(Factory& f,int n){for(int i=0;i<n;i++){f.tick++;f.beginPowerStep();f.finishPowerStep();}}
static Position where(K k){auto b=Factory::waterWorksBlueprint();for(const auto& n:b.parts)if(n.machine.kind==k)return {waterWorksOrigin.x+n.at.x,waterWorksOrigin.y+n.at.y};throw std::runtime_error("kind absent from waterworks");}
static Machine& machine(Factory& f,K k){return *f.at(where(k));}
static Factory plant(){auto f=empty();require(installWaterWorksIn(f),"install empty compact waterworks");add(f,{-8,7},K::GridInlet,2).power.rate=100;return f;}
static WaterParcel inventory(const Factory& f){WaterParcel sum;for(const auto& [p,m]:f.machines){for(size_t i=0;i<WaterStreamCount;i++)addWaterParcel(sum,storedWater(m,E(size_t(E::RawWater)+i)));sum.solids+=m.waterProcess.captured;}return sum;}
static void stopSources(Factory& f){machine(f,K::BoreholePump).enabled=false;machine(f,K::RainCollector).enabled=false;}
int main(int argc,char** argv){try{
 {Factory f;require(machineSpecs().size()==size_t(K::Count),"complete build catalogue retains stable original IDs and includes all new equipment");int count=0;for(const auto& [p,m]:f.machines)if(isWaterMachine(m.kind))count++;require(count==12,"fresh demo includes collection, full treatment, supply, sampling and reuse");auto b=Factory::waterWorksBlueprint();require(b.width==7&&b.height==5&&b.parts.size()==12,"the plant is a compact reusable process");for(const auto& n:b.links)require(validPowerLink(n.link)&&n.at.x>=0&&n.at.x<b.width&&n.at.y>=0&&n.at.y<b.height,"all return and reject routes are typed and in bounds");}
 {auto f=plant();advance(f,120);auto inv=inventory(f);double supplied=f.waterworks.extracted+f.waterworks.rainCollected;std::cout<<"Produced "<<f.waterworks.delivered<<" / well "<<f.waterworks.extracted<<" / rain "<<f.waterworks.rainCollected<<"\n";if(f.waterworks.delivered<50)for(const auto& [p,m]:f.machines)if(isWaterMachine(m.kind)){auto q=waterSample(m);std::cout<<machineSpec(m.kind).name<<" "<<m.status<<" / "<<powerContents(m)<<" / quality "<<q.solids<<","<<q.salt<<","<<q.bio<<" in "<<q.volume<<"\n";}require(f.waterworks.delivered>50&&f.water>0,"actual powered collection, treatment and delivery supplies factory stock");require(std::abs(inv.volume+f.water+f.waterworks.disposed.volume-supplied)<1e-5,"treatment splits and storage conserve every litre");require(std::abs(inv.solids+f.waterworks.supply.solids-f.waterworks.extracted-2*f.waterworks.rainCollected)<1e-5,"sand media, reject and supplied-water solids conserve the incoming load");require(std::abs(inv.salt+f.waterworks.supply.salt-6*f.waterworks.extracted-.2*f.waterworks.rainCollected)<1e-5,"membranes redistribute salt rather than deleting it");require(std::abs(inv.bio+f.waterworks.supply.bio+f.waterworks.killed-f.waterworks.extracted-4*f.waterworks.rainCollected)<1e-5,"UV biological reduction is recorded alongside surviving load");require(acceptableWater(f.waterworks.supply),"cumulative delivered water meets the game quality limits");require(f.powerContactFlow(where(K::SandFilter),where(K::MembraneFilter),E::FilteredWater)>0,"treatment throughput is measured at real ports");}
 {auto f=plant();stopSources(f);putWater(machine(f,K::CleanWaterTank),E::CleanWater,{10,3,50,5});advance(f,3);require(f.water==0&&machine(f,K::WaterOutlet).status.find("QUALITY HOLD")!=std::string::npos,"contaminated clean-labelled water cannot bypass the supply quality gate");require(f.configure(where(K::CleanWaterTank),"water-purge")&&f.configure(where(K::WaterOutlet),"water-purge"),"queue both actual held-water purges");advance(f,4);require(std::abs(machine(f,K::ConcentrateTank).power.store[size_t(E::Concentrate)]-10)<1e-6&&f.water==0,"unsafe water drains to reject instead of becoming clean stock or vanishing");}
 {auto f=plant();f.at({-8,7})->enabled=false;advance(f,24);require(f.waterworks.delivered==0&&f.waterworks.extracted==0,"rain alone cannot provide powered filtration or free groundwater");require(f.waterworks.rainCollected>0,"unpowered rain collection remains an intermittent independent source");putWater(machine(f,K::WaterOutlet),E::CleanWater,{5,0,0,0});advance(f,1);require(f.water==0,"even held clean water requires power for the factory delivery pump");}
 {auto f=plant();machine(f,K::RainCollector).enabled=false;f.tick=200;f.waterworks.aquifer=f.waterworks.aquiferCapacity=3;advance(f,2);require(f.waterworks.extracted<=3.000001&&f.waterworks.aquifer<1e-7,"dry weather and finite aquifer constrain extraction");}
 {auto f=plant();stopSources(f);f.waterworks.greywater={20,160,30,120};advance(f,100);auto inv=inventory(f);require(f.waterworks.recovered>0&&f.waterworks.recovered<=18.000001&&f.waterworks.delivered>0,"actual greywater can be reclaimed and retreated with finite recovery");require(std::abs(inv.volume+f.water+f.waterworks.greywater.volume-20)<1e-5,"reuse cannot multiply process water");}
 {auto f=plant();machine(f,K::ConcentrateTank).power.capacity=1;advance(f,400);require(machine(f,K::MembraneFilter).power.flow==0,"a full reject route eventually backs up membrane production");require(f.configure(where(K::ConcentrateTank),"water-haul"),"haul the held concentrate");bool resumed=false;for(int i=0;i<6;i++){advance(f,1);resumed|=machine(f,K::MembraneFilter).power.flow>0;}require(resumed&&f.waterworks.disposed.volume>0,"measured disposal frees real capacity and restores flow");}
 {auto f=plant();f.water=3;auto& filter=machine(f,K::SandFilter);filter.waterProcess.captured=50;filter.waterProcess.fouling=1.25;require(f.configure(where(K::SandFilter),"water-rinse"),"queue a real backwash");advance(f,1);require(!filter.waterProcess.rinse&&filter.waterProcess.captured<50,"backwash removes captured filter loading");require(std::abs(f.water-(3-2+f.waterworks.delivered))<1e-6&&machine(f,K::ConcentrateTank).waterProcess.loads[size_t(E::Concentrate)-size_t(E::RawWater)].solids>=50,"backwash spends two real litres and sends media solids to reject");}
 {auto f=empty();auto& source=add(f,{0,0},K::RainCollector);auto& a=add(f,{1,0},K::RawWaterTank);auto& b=add(f,{2,0},K::RawWaterTank);a.power.capacity=3;advance(f,5);double total=source.power.store[size_t(E::RawWater)]+a.power.store[size_t(E::RawWater)]+b.power.store[size_t(E::RawWater)];require(std::abs(total-f.waterworks.rainCollected)<1e-6&&b.power.store[size_t(E::RawWater)]>0,"touching matching reservoirs form a real bank without duplicating source water");require(!powerContactSupports(K::RawWaterTank,K::CleanWaterTank,E::CleanWater),"reservoir contacts cannot mix raw and clean circuits");}
 {auto f=empty();auto b=Factory::rotatedBlueprint(Factory::waterWorksBlueprint());require(f.stamp(b,{0,0}),"stamp a rotated water process with all typed routes");Position outlet{};for(const auto& [p,m]:f.machines)if(m.kind==K::WaterOutlet)outlet=p;add(f,nextPosition(outlet,1),K::GridInlet,3).power.rate=100;advance(f,60);require(f.waterworks.delivered>20,"rotated source, side reject and supply ports retain a functioning treatment line");}
 {auto f=plant();advance(f,30);machine(f,K::MembraneFilter).waterProcess.recovery=.9;machine(f,K::UVSterilizer).waterProcess.uvDose=2.25;require(f.captureBlueprint(waterWorksOrigin,{waterWorksOrigin.x+6,waterWorksOrigin.y+4},"my waterworks"),"capture a full process with routes and settings");auto plan=f.blueprints.back();require(f.stamp(plan,{20,20}),"reuse a captured plant elsewhere");for(const auto& n:plan.parts){auto m=f.at({20+n.at.x,20+n.at.y});for(size_t i=0;i<WaterStreamCount;i++)require(m->power.store[size_t(E::RawWater)+i]==0,"stamped plans do not clone stored water");require(m->waterProcess.captured==0&&m->waterProcess.sample.volume==0,"plans do not clone filter cake or observed samples");if(m->kind==K::MembraneFilter)require(m->waterProcess.recovery==.9,"plans retain chosen membrane recovery");if(m->kind==K::UVSterilizer)require(m->waterProcess.uvDose==2.25,"plans retain chosen disinfection dose");}
 auto file=std::filesystem::temp_directory_path()/"aftertaste-water-persistence.json";f.storageFile=file;require(f.save(),"save the water system");Factory loaded;loaded.storageFile=file;require(loaded.load()&&json(static_cast<const FactoryState&>(loaded))==json(static_cast<const FactoryState&>(f)),"all volume, loads, aquifer, filter state, settings and routes persist");auto valid=json(static_cast<const FactoryState&>(loaded));auto bad=json{{"version",17},{"factory",valid}};bad["factory"]["machines"][0]["machine"]["waterProcess"]["loads"][0]["salt"]=-1;{std::ofstream out(file);out<<bad;}require(!loaded.load()&&json(static_cast<const FactoryState&>(loaded))==valid,"invalid water quality is rejected without changing the current world");std::filesystem::remove(file);}
 {Factory f;f.water=0;f.farmProduce=10000;f.chemicals=100;for(auto& [p,m]:f.machines){if(m.kind==K::GridInlet){m.enabled=true;m.power.rate=100;}if(isFarmBed(m.kind))m.farmMoisture=.1;}bool irrigated=false;for(int i=0;i<80;i++){f.step();for(const auto& [p,m]:f.machines)if(isFarmBed(m.kind))irrigated|=m.farmMoisture>.25;}require(f.waterworks.delivered>20&&irrigated&&f.shipped>0,"waterworks supplies actual farm irrigation and factory production from an empty input buffer");require(f.waterworks.recovered>0||f.waterworks.greywater.volume>0,"real operating processes populate the greywater return system");}
 if(argc>1){std::ifstream in(argv[1]);json j;in>>j;auto before=j.at("factory").get<FactoryState>();Factory f;f.storageFile=argv[1];require(f.load(),"upgrade the supplied version 16 factory");require(f.machines.size()==before.machines.size()+12+Factory::reagentWorksBlueprint().parts.size(),"the saved demo receives twelve actual water facilities");for(const auto& [p,m]:before.machines)require(f.at(p)&&json(*f.at(p))==json(m),"all original machines, fuel, food, growing crops and energy remain exact");require(f.tick==before.tick&&f.water==before.water&&f.electricity==before.electricity&&f.chemicals==before.chemicals&&f.stock==before.stock,"installation neither advances time nor grants clean water or other input buffers");for(const auto& [p,m]:f.machines)if(isWaterMachine(m.kind))for(size_t n=0;n<WaterStreamCount;n++)require(m.power.store[size_t(E::RawWater)+n]==0,"new machinery starts empty until the simulation runs");}
 std::cout<<"PASS waterworks: "<<checks<<" checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL waterworks: "<<e.what()<<" (check "<<checks<<")\n";return 1;}}
